/// <reference types="vite/client" />
// Emscripten glue generated by scripts/build-wasm.sh into src/wasm/.
declare module "*/binfera.js" {
  interface BinferaModule {
    FS: { mkdir(path: string): void; writeFile(path: string, data: string | Uint8Array): void };
    callMain(args: string[]): number | undefined;
  }
  export default function createBinfera(options: {
    print: (line: string) => void;
    printErr: (line: string) => void;
    /** One byte of standard input per call; null at the end. */
    stdin?: () => number | null;
    instantiateWasm: (
      imports: WebAssembly.Imports,
      success: (instance: WebAssembly.Instance, module?: WebAssembly.Module) => void,
    ) => object;
  }): Promise<BinferaModule>;
}

declare module "7z-wasm/7zz.wasm?url" {
  const url: string;
  export default url;
}
